# 文件路径：examples/parse_session_log.py
# 解析一份 JSONL 会话日志，重建模型可见的对话并标出 turn/step 边界。
# 这是 Session.deriveMessages() 的一个简化教学模型；真实实现是缓存的且返回冻结消息。
import json
import sys

def derive_messages(events):
    """只投影 surface 事件，模拟 deriveMessages 的投影规则。

    user/message      -> user 消息
    assistant/message -> assistant 消息
    tool/result       -> 携带 tool-result 块的 user 消息
    turn/*, step/*, assistant/chunk, tool/call 不投影为消息
    """
    messages = []
    for ev in events:
        t = ev["type"]
        d = ev["data"]
        if t == "user/message":
            messages.append({"role": "user", "content": d["content"]})
        elif t == "assistant/message":
            messages.append({"role": "assistant", "content": d["message"]["content"]})
        elif t == "tool/result":
            messages.append({"role": "tool", "name": d["message"]["toolName"], "content": d["message"]["content"]})
    return messages

def main(path):
    with open(path, encoding="utf-8") as f:
        events = [json.loads(line) for line in f if line.strip()]

    # 第一遍：打印执行边界，理解 turn 与 step 的嵌套关系。
    for ev in events:
        d = ev["data"]
        if ev["type"] == "turn/start":
            print(f"[turn/start] turn={d['turn']}")
        elif ev["type"] == "turn/end":
            print(f"[turn/end]   turn={d['turn']} reason={d['reason']}")
        elif ev["type"] == "step/start":
            print(f"  [step/start] turn={d['turn']} step={d['step']}")
        elif ev["type"] == "step/end":
            print(f"  [step/end]   turn={d['turn']} step={d['step']}")
        elif ev["type"] == "assistant/chunk":
            print(f"    chunk: {d['chunk']['type']}")
        elif ev["type"] == "tool/call":
            print(f"    tool/call: {d['name']} args={d['arguments']}")

    # 第二遍：重建模型可见的派生历史。
    print("\n模型可见的派生消息：")
    for m in derive_messages(events):
        if m["role"] == "tool":
            print(f"  [tool] {m['name']}: {m['content']}")
        else:
            print(f"  [{m['role']}] {m['content']}")

if __name__ == "__main__":
    main(sys.argv[1])

// 文件路径：示例代码，演示一次完整的 chunk 序列
import { CallId, type StreamChunk } from '@deepseek-ai/dsh-llm'

async function* exampleChunks(): AsyncIterable<StreamChunk> {
  // 1. Start each content block with block-start.
  // 开启一个文本块，index 为 0
  yield { type: 'block-start', index: 0, blockType: 'text' }

  // 2. Stream text through text-delta.
  // 文本增量，可拆成多个分片
  yield { type: 'text-delta', index: 0, text: 'runoob' }
  yield { type: 'text-delta', index: 0, text: ' 教程' }

  // 3. End each content block with block-end and the complete block.
  // 用完整块结束，index 与 block-start 一致
  yield {
    type: 'block-end',
    index: 0,
    block: { type: 'text', text: 'runoob 教程' },
  }

  // 4. Tool-call block.
  // 开启一个工具调用块，index 为 1
  yield { type: 'block-start', index: 1, blockType: 'tool-call' }
  // 工具名与参数增量，id 用 CallId 工厂生成
  yield {
    type: 'tool-call-delta',
    index: 1,
    id: CallId('call-123'),
    name: 'bash',
    argumentsDelta: '{"command":"echo runoob"}',
  }
  // 用完整块结束，arguments 是拼好的 JSON 文本
  yield {
    type: 'block-end',
    index: 1,
    block: {
      type: 'tool-call',
      id: CallId('call-123'),
      name: 'bash',
      arguments: '{"command":"echo runoob"}',
    },
  }

  // 5. Token usage.
  // 报告 token 用量，必须在 finish 之前
  yield { type: 'usage', usage: { inputTokens: 100, outputTokens: 50 } }

  // 6. Finish reason.
  // 最后一个分片，声明结束原因
  yield { type: 'finish', reason: { kind: 'stop' } }
  // Alternatively, { kind: 'tool-calls' } requests tool execution.
}

// 文件路径：my-plugins/permission-gate/src/index.ts
// 一个基于 tools/pre-execute 的权限门禁插件。
// 它返回类型化的决策：命中黑名单就 deny，否则调用 next() 委托下去。
import type { Context } from '@deepseek-ai/cordis'
import type { PreToolDecision, ToolExecution } from '@deepseek-ai/dsh-tools'

// 黑名单：runoob 项目里禁止直接写文件系统的工具。
// 这里用最简单的集合演示；真实项目里可以查数据库、问审批服务。
const DENY_TOOLS = new Set(['fs_write', 'fs_edit'])

// 策略判定函数：返回这次调用是否被允许。
// exec 携带不可变的调用身份（callId、name、arguments、agent、token、signal）。
async function isAllowed(exec: ToolExecution): Promise<boolean> {
  if (DENY_TOOLS.has(exec.name)) return false
  // 额外示例：runoob 演示里禁止修改 .env 文件（参数在进入策略前已被冻结）。
  const raw = exec.arguments as { path?: string }
  if (typeof raw.path === 'string' && raw.path.includes('.env')) return false
  return true
}

export const name = 'permission-gate'

export function apply(ctx: Context) {
  // tools/pre-execute 是 waterfall：监听器可以返回决策，或调用 next() 委托。
  ctx.on('tools/pre-execute', async (exec, next): Promise<PreToolDecision> => {
    if (!(await isAllowed(exec))) {
      // 返回 deny 会立即终止这次调用，后续监听器不再执行。
      return { kind: 'deny', reason: 'Denied by policy: this tool is not allowed in the runoob workspace.' }
    }
    // 放行：把决定权交给流水线中后续的监听器。
    return next()
  })
}

// 文件路径：packages/my-shell/src/run.ts
// 运行一个子进程，并正交上报三个独立事实：timedOut、signal、exitCode。
import { spawn, type ChildProcess } from 'node:child_process'

export interface RunResult {
  timedOut: boolean      // 独立事实 1：是否超时
  signal: NodeJS.Signals | null // 独立事实 2：是否被信号终止
  exitCode: number | null       // 独立事实 3：退出码
  stdout: string
  stderr: string
}

export function run(argv: string[], timeoutMs: number): Promise<RunResult> {
  return new Promise((resolve, reject) => {
    const child: ChildProcess = spawn(argv[0], argv.slice(1), {
      stdio: ['ignore', 'pipe', 'pipe'],
    })
    let stdout = ''
    let stderr = ''
    child.stdout.on('data', (d: Buffer) => (stdout += d))
    child.stderr.on('data', (d: Buffer) => (stderr += d))

    // 独立事实 1 单独维护：超时是一个标志，与退出码无关。
    let timedOut = false
    const timer = setTimeout(() => {
      timedOut = true
      child.kill('SIGTERM') // 超时触发终止
    }, timeoutMs)

    child.on('close', (code, signal) => {
      clearTimeout(timer)
      // 三个字段各自独立返回：进程可能 timedOut=true 且 exitCode=0，
      // 因为它在超时后捕获了 SIGTERM 并以 0 退出。
      resolve({ timedOut, signal, exitCode: code, stdout, stderr })
    })
    child.on('error', reject)
  })
}
